// The paid product's help centre (preview, noindex): five short guides per
// language, generated by scripts/seo/generate-help-pages.ts. Same slug in every
// language; English at /help/<slug>/, the others at /<lang>/help/<slug>/.

export const HELP_TOPICS = ['setup', 'suppliers', 'verdict', 'api', 'security'] as const
export type HelpTopic = (typeof HELP_TOPICS)[number]
export const HELP_LANGS = ['en', 'es', 'de', 'fr', 'pt', 'it', 'ca', 'zh', 'ja', 'th'] as const
export type HelpLang = (typeof HELP_LANGS)[number]

export function helpPath(topic: HelpTopic | null, lang: string): string {
  const l = (HELP_LANGS as readonly string[]).includes(lang) ? lang : 'en'
  return `${l === 'en' ? '' : `/${l}`}/help/${topic ? `${topic}/` : ''}`
}
